PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS trucks(id INTEGER PRIMARY KEY,truck_code TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'LOADING',total_sets INTEGER NOT NULL DEFAULT 24 CHECK(total_sets=24),completed_sets INTEGER NOT NULL DEFAULT 0 CHECK(completed_sets BETWEEN 0 AND 24),created_at TEXT NOT NULL,source_mode TEXT NOT NULL DEFAULT 'DEMO',source_date TEXT);
CREATE TABLE IF NOT EXISTS dollys(id INTEGER PRIMARY KEY,truck_id INTEGER NOT NULL REFERENCES trucks(id),dolly_number INTEGER NOT NULL CHECK(dolly_number BETWEEN 1 AND 8),dolly_pair_number INTEGER NOT NULL CHECK(dolly_pair_number BETWEEN 1 AND 4),status TEXT NOT NULL DEFAULT 'PENDING',UNIQUE(truck_id,dolly_number));
CREATE TABLE IF NOT EXISTS sequences(id INTEGER PRIMARY KEY,truck_id INTEGER NOT NULL REFERENCES trucks(id),sequence_number INTEGER NOT NULL CHECK(sequence_number BETWEEN 0 AND 9999),load_index INTEGER NOT NULL CHECK(load_index BETWEEN 1 AND 24),model TEXT NOT NULL,sd TEXT NOT NULL,hand TEXT NOT NULL CHECK(hand IN ('LH','RH')),position TEXT NOT NULL CHECK(position IN ('FR','RR')),expected_panel_code TEXT NOT NULL,expected_armrest_code TEXT NOT NULL,expected_armrest_sd TEXT,expected_garnish_code TEXT NOT NULL,required_curing_minutes REAL NOT NULL CHECK(required_curing_minutes>=0),dolly_number INTEGER NOT NULL CHECK(dolly_number BETWEEN 1 AND 8),dolly_level TEXT NOT NULL CHECK(dolly_level IN ('TOP','BOTTOM')),dolly_column INTEGER NOT NULL CHECK(dolly_column BETWEEN 1 AND 6),status TEXT NOT NULL DEFAULT 'PENDING',source_order_id INTEGER,source_order INTEGER,reference TEXT,suffix TEXT,garnish_required INTEGER NOT NULL DEFAULT 1,UNIQUE(truck_id,sequence_number,hand,position),UNIQUE(truck_id,load_index,hand,position),UNIQUE(truck_id,dolly_number,dolly_level,dolly_column));
CREATE TABLE IF NOT EXISTS sets(id INTEGER PRIMARY KEY,truck_id INTEGER NOT NULL REFERENCES trucks(id),sequence_id INTEGER NOT NULL UNIQUE REFERENCES sequences(id),slot_number INTEGER NOT NULL,panel_barcode TEXT NOT NULL,panel_plc_ok INTEGER NOT NULL CHECK(panel_plc_ok=1),armrest_barcode TEXT NOT NULL,armrest_plc_ok INTEGER NOT NULL CHECK(armrest_plc_ok=1),armrest_curing_minutes REAL NOT NULL,garnish_barcode TEXT NOT NULL,garnish_plc_ok INTEGER NOT NULL CHECK(garnish_plc_ok IN (0,1)),garnish_skipped INTEGER NOT NULL DEFAULT 0 CHECK(garnish_skipped IN (0,1)),cycle_start_time TEXT NOT NULL,cycle_end_time TEXT NOT NULL,operator_id TEXT NOT NULL,CHECK((garnish_skipped=1 AND garnish_plc_ok=0) OR (garnish_skipped=0 AND garnish_plc_ok=1)));
CREATE TABLE IF NOT EXISTS runtime(id INTEGER PRIMARY KEY CHECK(id=1),payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,time TEXT NOT NULL,message TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS print_jobs(id INTEGER PRIMARY KEY,truck_id INTEGER NOT NULL REFERENCES trucks(id),block INTEGER NOT NULL,zpl TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',error TEXT,UNIQUE(truck_id,block));
CREATE TABLE IF NOT EXISTS components(barcode TEXT PRIMARY KEY,kind TEXT NOT NULL,model TEXT NOT NULL,hand TEXT NOT NULL,position TEXT NOT NULL,color TEXT NOT NULL,finish TEXT NOT NULL,bonded_at TEXT);

CREATE TABLE IF NOT EXISTS runtime_archives(id INTEGER PRIMARY KEY AUTOINCREMENT,truck_id INTEGER NOT NULL REFERENCES trucks(id),payload TEXT NOT NULL,created_at TEXT NOT NULL,reason TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS dolly_layout(id INTEGER PRIMARY KEY CHECK(id=1),payload TEXT NOT NULL);
